BEGIN;
DO $qa$
DECLARE b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();m uuid:=gen_random_uuid();d1 uuid:=gen_random_uuid();d2 uuid:=gen_random_uuid();o1 uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();o3 uuid:=gen_random_uuid();ch uuid:=gen_random_uuid();n2 bigint:=1000000000000+floor(random()*1e12)::bigint;desk1 text:='qa-'||gen_random_uuid();desk2 text:='qa-'||gen_random_uuid();v jsonb;checks int:=0;
BEGIN
 INSERT INTO public.ff_branches(id,code,name) VALUES(b,'qa-queue-'||b,'QA queue');
 INSERT INTO auth.users(id) VALUES(c),(m);
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(c,'QA STEP12 cashier','cashier',true),(m,'QA STEP12 manager','manager',true);
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(c,b);
 INSERT INTO public.ff38_staff_permission_overrides(user_id,permission_key,allowed,updated_by) VALUES(c,'cancel_order',true,m),(c,'assign_driver',true,m),(c,'edit_order',true,m);
 INSERT INTO public.ff_drivers(id,name,branch_id) VALUES(d1,'QA driver one',b),(d2,'QA driver two',b);
 INSERT INTO public.ff38_driver_presence(driver_id,state,checked_in_at,last_seen_at) VALUES(d1,'busy',now(),now()),(d2,'busy',now(),now()) ON CONFLICT(driver_id) DO UPDATE SET state=excluded.state,checked_in_at=excluded.checked_in_at,last_seen_at=excluded.last_seen_at;
 INSERT INTO public.ff_orders(id,order_number,branch_id,phone_snapshot,business_date,driver_id,status) VALUES(o1,-(1+floor(random()*1e12)::bigint),b,'000000000',public.ff_business_date(now()),d1,'sent'),(o2,n2,b,'000000000',public.ff_business_date(now()),d2,'sent'),(o3,-(1+floor(random()*1e12)::bigint),b,'000000000',public.ff_business_date(now()),NULL,'new');
 INSERT INTO public.ff38_delivery_tasks(order_id,driver_id) VALUES(o1,d1),(o2,d2);
 INSERT INTO public.ff_luxe_cashier_desks(code,label,branch_id,sort_order) VALUES(desk1,'QA desk 1',b,1),(desk2,'QA desk 2',b,2);
 INSERT INTO public.ff_luxe_cashier_staff_desks(user_id,desk_code,assigned_by) VALUES(c,desk1,m);
 INSERT INTO public.ff_luxe_cashier_order_desks(order_id,desk_code) VALUES(o1,desk1),(o2,desk2),(o3,desk2);
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 PERFORM public.ff49_cashier_receive(o2);
 PERFORM public.ff49_cashier_invoice(o2,NULL);
 INSERT INTO public.ff50_order_changes(id,order_id,old_items,new_items,old_total,new_total,reason,requested_by,status) VALUES(ch,o2,'[]','[]',0,0,'QA change',m,'approved');
 SET LOCAL ROLE authenticated;PERFORM set_config('request.jwt.claim.sub',c::text,true);
 v:=public.ff60_operational_queue(b,200);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(v) x WHERE x->>'id'=o1::text) OR EXISTS(SELECT FROM jsonb_array_elements(v) x WHERE x->>'id' IN(o2::text,o3::text)) THEN RAISE EXCEPTION 'Queue scope';END IF;checks:=checks+1;
 v:=public.ff60_list_workflow(o1,30);IF jsonb_typeof(v)<>'array' THEN RAISE EXCEPTION 'Own workflow inaccessible';END IF;checks:=checks+1;
 BEGIN PERFORM public.ff60_list_workflow(o2,30);RAISE EXCEPTION 'Foreign workflow allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff27_document_invoice(b,n2::text,'QA reference');RAISE EXCEPTION 'Foreign document allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff50_change_request(o2,'[{"name":"QA","qty":1,"price":100}]','QA change reason');RAISE EXCEPTION 'Foreign change request allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff50_change_service_confirm(ch);RAISE EXCEPTION 'Foreign change confirmation allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff38_dispatch(o3,d1);RAISE EXCEPTION 'Foreign dispatch allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff38_cancel_unassigned_order(o3,'QA cancellation');RAISE EXCEPTION 'Foreign unassigned cancellation allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff_luxe_cancel_assigned(o2,'QA cancellation');RAISE EXCEPTION 'Foreign assigned cancellation allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 v:=public.ff27_document_invoice(b,n2::text,'QA manager reference');IF v->>'documented'<>'true' THEN RAISE EXCEPTION 'Manager document broken';END IF;checks:=checks+1;
 v:=public.ff_luxe_cancel_assigned(o2,'QA manager cancellation');IF v->>'cancelled'<>'true' THEN RAISE EXCEPTION 'Manager cancel broken';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);
 BEGIN PERFORM public.ff_luxe_ack_cashier_cancel(o2);RAISE EXCEPTION 'Foreign ack allowed' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 v:=public.ff_luxe_ack_cashier_cancel(o2);IF v->>'acknowledged'<>'true' THEN RAISE EXCEPTION 'Manager ack broken';END IF;checks:=checks+1;
 RESET ROLE;
 IF (SELECT status FROM public.ff_orders WHERE id=o3)<>'new' OR EXISTS(SELECT FROM public.ff38_dispatch_offers WHERE order_id=o3) OR (SELECT status FROM public.ff50_order_changes WHERE id=ch)<>'approved' THEN RAISE EXCEPTION 'Denied actions mutated data';END IF;checks:=checks+1;
 IF checks<>14 THEN RAISE EXCEPTION 'Incomplete desk checks';END IF;
END $qa$;
SELECT 'PASS STEP12 desk operations: 14 assertions' result;
ROLLBACK;
